[DataMemberAttribute("salesOrderGuideResponseList"),
    AifCollectionTypeAttribute('_salesOrderGuideResponseList', Types::Class, classStr(METSalesOrderGuideResponseContract)),
    AifCollectionTypeAttribute("return", Types::Class, classStr(METSalesOrderGuideResponseContract))]
public List parmSalesOrderGuideResponseList(List _salesOrderGuideResponseList = salesOrderGuideResponseList)
{
    salesOrderGuideResponseList = _salesOrderGuideResponseList;
    return salesOrderGuideResponseList;
}

/// <summary>
/// Method to specify the customer account number
/// </summary>
/// <param name = "_custAccount">customer account number</param>
/// <returns>returns the customer account number</returns>
[
    DataMemberAttribute('CustomerAccountNumber')
]
public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    if (!prmIsDefault(_custAccount))
    {
        custAccount = _custAccount;
    }
    return custAccount;
}
